var EXTRA=[{dot:"gray",j:"International Orthopaedics",h:"Anche la frattura di bacino può nascondere una lesione legamentosa del ginocchio",v:"Una coorte su fratture del bacino e dell'acetabolo trova che una parte non trascurabile dei pazienti ha anche una lesione legamentosa del ginocchio associata, più frequente con le fratture della parete posteriore — un promemoria a non fermare l'esame al solo osso.",pmid:'42773172',doi:'10.1007/s00264-026-07047-z',temi:["trauma","legamenti"]},{dot:"gray",j:"Journal of Pain Research",h:"Nel diabetico l'esercizio terapeutico per l'artrosi protegge meno",v:"Una coorte cinese appaiata per propensione mostra che il diabete di tipo 2 riduce l'effetto protettivo della terapia con esercizio sul rischio di infortunio nei pazienti con gonartrosi — un fattore da considerare nella riabilitazione conservativa prima della chirurgia.",pmid:'42774425',doi:'10.2147/JPR.S635780',temi:["artrosi","diabete"]},{dot:"gray",j:"The Archives of Bone and Joint Surgery",h:"Il disturbo da uso di alcol pesa sulle complicanze della protesi",v:"Una coorte sul database globale TriNetX associa il disturbo da uso di alcol a un rischio più alto di complicanze mediche e chirurgiche dopo protesi totale di ginocchio — utile da indagare nell'anamnesi prima di programmare l'intervento.",pmid:'42775051',doi:'10.22038/ABJS.2026.90939.4121',temi:["protesi totale","complicanze"]},{dot:"gray",j:"Journal of Experimental Orthopaedics",h:"Come si fissa l'innesto rotuleo cambia la sua rigidità in laboratorio",v:"Studio cadaverico su coppie di ginocchia appaiate: la fissazione con dispositivo a compressione trasversale (cross-pin) si comporta diversamente dalla vite a interferenza sull'innesto osso-tendine-osso, in spostamento e rigidità — dato di banco, non ancora clinico.",pmid:'42775255',doi:'10.1002/jeo2.70921',temi:["fissazione innesto","biomeccanica"]},{dot:"gray",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Gli indici di infiammazione sistemica cambiano col sesso dopo il LCA",v:"Una coorte retrospettiva trova indici di infiammazione più alti nelle donne con sindrome metabolica dopo ricostruzione del LCA rispetto agli uomini — un tassello di biologia perioperatoria, non ancora legato a un esito clinico.",pmid:'42775304',doi:'10.1002/ars2.70091',temi:["infiammazione","sindrome metabolica"]},{dot:"gray",j:"Physiotherapy Research International",h:"La TENS ad alta frequenza aggiunta all'esercizio non convince ancora",v:"Trial randomizzato con controllo simulato: aggiungere la stimolazione elettrica nervosa transcutanea ad alta frequenza all'esercizio terapeutico per l'artrosi di ginocchio non mostra un beneficio aggiuntivo chiaro in un campione di dimensioni contenute — il margine di incertezza resta ampio.",pmid:'42775508',doi:'10.1002/pri.70351',temi:["artrosi","terapia conservativa"]},{dot:"gray",j:"Orthopedics",h:"Negli ottuagenari la protesi di ginocchio pesa di più nei primi 90 giorni",v:"Un ampio registro assicurativo statunitense mostra che negli ultraottantenni le complicanze mediche precoci dopo protesi totale sono più frequenti, ma il rischio di revisione a un anno è più basso che nei pazienti più giovani — un argomento per calibrare il colloquio prognostico sull'età, non solo sulla tecnica.",pmid:'42775938',doi:'10.3928/01477447-20260820-01',temi:["protesi totale","età avanzata"]},{dot:"gray",j:"JBJS Reviews",h:"Protesi d'anca e ginocchio nell'adolescente: una fotografia rara ma utile",v:"Revisione sistematica su protesi articolari maggiori in pazienti pediatrici e adolescenti, popolazione rara ma in crescita per patologie reumatiche o post-traumatiche severe: infezione, mobilizzazione asettica e revisione restano i rischi principali da discutere in questa fascia d'età.",pmid:'42777096',doi:'10.2106/JBJS.RVW.26.00096',temi:["adolescente","protesi"]},{dot:"gray",j:"Clinical Biomechanics",h:"Quante sedute di biofeedback del cammino servono dopo il LCA",v:"Studio di dose-risposta: individua un numero minimo di sedute di biofeedback del cammino sufficiente a correggere il pattern di carico dopo ricostruzione del LCA, utile per calibrare la riabilitazione senza eccedere in sedute superflue.",pmid:'42777489',doi:'10.1016/j.clinbiomech.2026.106974',temi:["riabilitazione","biomeccanica del cammino"]},{dot:"gray",j:"BMJ Open",h:"La riabilitazione a distanza dopo protesi di ginocchio è fattibile",v:"Trial di fattibilità in Iran: un programma di teleriabilitazione dopo protesi totale di ginocchio ha un tasso di adesione alto e pochi abbandoni, aprendo la strada a un trial randomizzato di efficacia più ampio.",pmid:'42778252',doi:'10.1136/bmjopen-2025-112566',temi:["riabilitazione","telemedicina"]},{dot:"gray",j:"Acta Orthopaedica",h:"Quanto si muove una protesi di ginocchio sotto carico, in laboratorio",v:"Revisione sistematica sulla misura per stereofotogrammetria (RSA) dello spostamento indotto dal carico nelle protesi di ginocchio: sintetizza il metodo più usato per prevedere precocemente il rischio di mobilizzazione, senza ancora una soglia unica condivisa.",pmid:'42776611',doi:'10.2340/17453674.2026.46318',temi:["protesi totale","biomeccanica"]},{dot:"gray",j:"Frontiers in Bioengineering and Biotechnology",h:"Un modello concettuale per capire perché gli ortobiologici funzionano solo a volte",v:"Rassegna integrativa che propone la metafora «seme e terreno» per l'artrosi di ginocchio: il seme è il prodotto ortobiologico iniettato, il terreno è la biologia sistemica del paziente più il microambiente del tessuto bersaglio — un framework concettuale, non ancora validato in trial randomizzati, per capire perché lo stesso trattamento dia risultati diversi da persona a persona.",pmid:'42775215',doi:'10.3389/fbioe.2026.1946746',temi:["ortobiologici","artrosi"]}];
var SCOPERTE=[{t:"L'intelligenza artificiale generativa nella protesi d'anca e ginocchio, ci siamo davvero?",v:"Una revisione sistematica su 23 studi mostra che ChatGPT risponde alle domande frequenti dei pazienti in modo giudicato accurato quanto un chirurgo da valutazioni cieche di clinici, e redige consensi informati più leggibili di quelli standard (livello di lettura 12,6 contro 16,8); sul supporto alla decisione clinica vera e propria l'evidenza resta acerba (alta sensibilità ma bassa specificità nel prevedere l'idoneità chirurgica). Vale la deviazione perché è il tuo stesso interesse dichiarato per l'IA applicata alla medicina, letto con occhio critico invece che entusiasta.",pmid:'42757394',doi:'10.2106/JBJS.OA.26.00077',temi:["intelligenza artificiale","comunicazione col paziente"]},{t:"Un algoritmo cinese prova a prevedere chi, fra i pazienti con artrosi di ginocchio, cadrà per primo",v:"Un modello di apprendimento automatico interpretabile, addestrato su una coorte nazionale cinese (CHARLS) e validato su una coorte ospedaliera indipendente, individua problemi sensoriali (vista, udito) e sintomi depressivi come i predittori più forti di caduta nei pazienti con artrosi di ginocchio (AUC 0,836). Una direzione lontana dalla sala operatoria, dove il ginocchio diventa il punto di partenza per prevenire un evento che spesso finisce comunque in ortopedia.",pmid:'42759165',doi:'10.1016/j.archger.2026.106410',temi:["intelligenza artificiale","prevenzione cadute"]},{t:"In Cina si discute il futuro della protesi parziale di ginocchio, fra AI e stampa 3D",v:"Una rassegna narrativa di due ortopedici di Pechino ripercorre l'evoluzione della protesi monocompartimentale verso pianificazione assistita da intelligenza artificiale, strumentario paziente-specifico stampato in 3D e chirurgia robotica, ammettendo però che manca ancora uno standard condiviso per il posizionamento della protesi. Vale la deviazione perché è uno sguardo diretto su come la scuola cinese sta pensando la stessa tecnica che tu pratichi ogni settimana, con un'esplicita ambizione di internazionalizzare i propri protocolli.",pmid:'42778312',doi:'10.3760/cma.j.cn112137-20260105-00048',temi:["mondo orientale","protesi robotica"]}];
var SOC={"1": {"video": "Una meta-analisi di nove studi, su 910 ginocchia operate di legamento crociato anteriore, mette a confronto chi ha avuto anche la riparazione di una radice meniscale posteriore lesionata sul lato esterno del ginocchio con chi non ne aveva bisogno. I punteggi di funzione risultano sovrapponibili, e la riparazione guarisce tecnicamente bene in circa otto casi su dieci. Il punto onesto: il confronto che conta di più — riparare o lasciare una radice davvero lesionata — esiste solo in due studi piccoli, non abbastanza per una risposta definitiva.", "linkedin": "Meta-analisi di 9 studi comparativi retrospettivi, 910 ginocchia (J ISAKOS, set 2026): ACLR con riparazione concomitante della radice meniscale posteriore laterale non mostra differenze significative su IKDC (MD -0,43; IC 95% -2,78/1,93), Lysholm, Tegner o traslazione tibiale anteriore rispetto a ACLR isolata con menisco integro. Guarigione 81% (89/110). Il confronto diretto riparazione-vs-non riparazione resta limitato a 2 studi.", "instagram": "🦵 Quando il legamento crociato anteriore si rompe, a volte si lesiona anche una radice del menisco. Una meta-analisi su oltre 900 ginocchia mostra che ripararla dà risultati simili a chi non ne aveva bisogno — la tecnica funziona, ma il confronto più onesto (riparare o no) resta ancora povero di dati.", "pazienti": "Quando il legamento centrale del ginocchio si rompe, può rompersi anche un punto di aggancio del menisco. Un'analisi di più studi, su oltre 900 ginocchia operate, mostra che chi ha avuto anche questa riparazione recupera come chi non ne aveva bisogno, e che la riparazione guarisce bene nella maggior parte dei casi."}};
var SOCV={"1": {"video": {"chir": ["Una meta-analisi di nove studi comparativi, pubblicata sul Journal of ISAKOS, mette a confronto 910 ginocchia operate di ricostruzione del legamento crociato anteriore: in alcune è stata riparata anche una radice meniscale posteriore lesionata sul lato esterno, in altre il menisco era integro.", "Il risultato: nessuna differenza significativa su IKDC, Lysholm, Tegner o sulla lassità misurata con l'artrometro fra i due gruppi. La riparazione, tecnicamente, guarisce bene in circa otto casi su dieci secondo i criteri di ciascuno studio.", "Il punto che conta di più: il confronto che risponde alla vera domanda clinica — riparare o lasciare non trattata una radice davvero lesionata — esiste solo in due studi piccoli. Troppo pochi per dire con certezza che la riparazione cambi l'esito rispetto al non farla."], "misto": ["Uno studio ha riunito i dati di nove ricerche su oltre 900 ginocchia operate di legamento crociato anteriore, per capire se riparare anche una piccola lesione del menisco, in un punto chiamato radice, cambi il risultato dell'intervento.", "I punteggi di funzione e stabilità sono risultati simili sia che la radice fosse stata riparata sia che il menisco fosse integro in partenza. E la riparazione, quando eseguita, guarisce bene nella grande maggioranza dei casi.", "Il limite onesto: gli studi che confrontano davvero riparare contro non riparare una radice lesionata sono solo due, e piccoli — non bastano per una conclusione definitiva. È un buon punto di partenza, non un punto di arrivo."], "pazienti": ["A volte, quando si rompe il legamento centrale del ginocchio, si lesiona anche un piccolo punto di aggancio del menisco chiamato radice. Uno studio ha messo insieme i risultati di più ricerche per capire se ripararlo faccia la differenza.", "Buona notizia sulla tecnica: quando si ripara, guarisce bene nella maggior parte dei casi. E chi ha avuto la riparazione recupera in modo simile a chi non ne aveva bisogno.", "Notizia onesta sul dubbio di fondo: gli studi che confrontano davvero riparare o no una radice lesionata sono ancora pochi — serve altra ricerca prima di dire con certezza quanto benefico in più dia la riparazione."]}, "reel": {"chir": ["[910 ginocchia, 9 studi] Riparare la radice meniscale laterale insieme al LCA non cambia IKDC, Lysholm, Tegner o lassità rispetto a menisco integro.", "[Il numero che conta] Guarigione 81% — ma riparare-contro-non-riparare è stato testato solo in 2 studi piccoli.", "[Il limite] Nessuna stratificazione per tecnica di fissazione; eterogeneità alta su più esiti."], "misto": ["[Una radice del menisco, riparata o no] Una meta-analisi su oltre 900 ginocchia confronta i due scenari dopo ricostruzione del LCA.", "[Il risultato] Punteggi simili nei due gruppi, e la riparazione guarisce bene quasi sempre.", "[Il limite onesto] Solo due studi piccoli confrontano davvero riparare contro non riparare."], "pazienti": ["[Una radice del menisco lesionata insieme al legamento] Che succede se viene riparata?", "[La buona notizia] Guarisce bene, e chi la ripara recupera come chi non ne aveva bisogno.", "[La notizia onesta] Gli studi che lo confermano davvero sono ancora pochi."]}, "linkedin": {"chir": ["Meta-analisi di 9 studi comparativi retrospettivi (J ISAKOS, set 2026), 910 ginocchia: ACLR + riparazione concomitante della radice meniscale posteriore laterale vs ACLR isolata a menisco integro.", "Nessuna differenza significativa su IKDC (MD -0,43; IC 95% -2,78/1,93; p=0,72), Lysholm, Tegner o traslazione tibiale anteriore all'artrometro. Guarigione 81% (89/110) secondo i criteri di ogni studio.", "Il confronto che conta di più — repair vs non-repair su radice realmente lesionata — è riportato da 2 soli studi, senza differenze significative a 2 anni ma con potere statistico insufficiente per concludere."], "misto": ["Una revisione di più studi ha confrontato, dopo la ricostruzione del legamento crociato anteriore, chi aveva avuto anche la riparazione di una lesione del menisco (nel punto di aggancio posteriore) con chi non ne aveva bisogno.", "I punteggi di funzione sono risultati sovrapponibili nei due gruppi, e la riparazione guarisce bene in circa otto casi su dieci.", "Il punto onesto: il confronto diretto fra riparare e non riparare una lesione reale esiste solo in due studi piccoli — un'area dove serve ancora ricerca, non certezza."], "pazienti": ["Quando il legamento centrale del ginocchio si rompe, a volte si lesiona anche un piccolo punto di aggancio del menisco.", "Un'analisi di più studi, su oltre 900 ginocchia, mostra che ripararlo dà un recupero simile a chi non ne aveva bisogno, e che la riparazione guarisce bene nella maggior parte dei casi.", "Detto con onestà: gli studi che confrontano davvero riparare o no sono ancora pochi, quindi la certezza assoluta non c'è ancora."]}, "instagram": {"chir": ["📊 910 ginocchia, 9 studi: ACLR + repair radice laterale vs ACLR isolata, nessuna differenza su IKDC/Lysholm/Tegner.", "🩹 Guarigione tecnica 81% — ma repair-vs-non-repair testato solo in 2 studi piccoli.", "⚠️ Eterogeneità alta, nessuna stratificazione per tecnica di fissazione."], "misto": ["🦵 Una radice del menisco lesionata insieme al LCA: ripararla cambia il risultato?", "📈 Su oltre 900 ginocchia, i punteggi sono simili con o senza riparazione — e la riparazione guarisce bene.", "🔍 Il confronto diretto riparare/non riparare esiste solo in due studi piccoli: serve altra ricerca."], "pazienti": ["🦵 A volte, quando si rompe il legamento del ginocchio, si lesiona anche un pezzetto del menisco.", "✅ Ripararlo guarisce bene, e il recupero è simile a chi non ne aveva bisogno.", "📚 Gli studi che lo confermano del tutto sono ancora pochi: la ricerca continua."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #LegamentoCrociato #ChirurgiaDelGinocchio", "instagram": "#ortopedia #legamentocrociatoanteriore #menisco #chirurgiadelginocchio #medicinasportiva #jisakos #traumatologia #ricercaortopedica #ginocchio", "kw": "radice meniscale, riparazione menisco, legamento crociato anteriore"}};
var NLB={"1": {"prof": ["Riparare la radice meniscale laterale nel LCA: una meta-analisi senza beneficio dimostrato", "Una revisione di 9 studi comparativi su 910 ginocchia operate di legamento crociato anteriore non trova differenze significative su IKDC, Lysholm, Tegner o lassità strumentale fra chi ha ricevuto anche la riparazione di una radice meniscale posteriore laterale lesionata e chi aveva il menisco integro; la riparazione guarisce bene nella grande maggioranza dei casi.", "Nota critica: il confronto più informativo — riparare contro non riparare una radice davvero lesionata — è stato condotto solo in due studi piccoli, insufficienti per una risposta definitiva; la revisione riguarda inoltre la radice laterale, non la mediale più frequente nella pratica quotidiana."], "mix": ["Riparare la radice meniscale laterale nel LCA: una meta-analisi senza beneficio dimostrato", "Una revisione di più studi, su oltre 900 ginocchia operate di legamento crociato anteriore, ha confrontato chi ha avuto anche la riparazione di una radice meniscale lesionata (parte posteriore di attacco del menisco, lato esterno) con chi aveva il menisco integro. I punteggi di funzione e stabilità del ginocchio sono risultati simili nei due gruppi, e la riparazione guarisce bene nella grande maggioranza dei casi.", "Nota sul limite: il confronto che risponde davvero alla domanda clinica — riparare o lasciare non trattata una radice lesa — è stato fatto solo in due studi piccoli, troppo pochi per una conclusione solida."], "paz": ["Una radice del menisco lesionata insieme al legamento del ginocchio: che cosa dicono gli studi", "Quando il legamento crociato anteriore si rompe, a volte si lesiona anche un punto di attacco del menisco chiamato «radice». Un'analisi di diversi studi, su oltre 900 ginocchia operate, mostra che chi ha avuto anche la riparazione della radice recupera in modo simile a chi non ne aveva bisogno, e che la riparazione tecnicamente riesce bene nella maggior parte dei casi.", "Nota rassicurante: la tecnica funziona ed è considerata sicura dai chirurghi; gli studi non hanno però ancora confrontato abbastanza casi per dire con certezza quanto benefico in più aggiunga rispetto a non intervenire sulla radice."], "kw": "radice meniscale, menisco laterale, legamento crociato anteriore"}, "2": {"prof": ["Il rinforzo laterale extra-articolare del ginocchio tiene bene a sei anni", "Una coorte francese su 265 pazienti operati di legamento crociato anteriore con tecnica combinata intra- ed extra-articolare (tenodesi laterale secondo MacIntosh modificato, con augmentazione di gracilis) riporta un tasso di rottura dell'innesto basso e un rientro allo sport elevato a un follow-up minimo di sei anni.", "Nota critica: il rientro al livello sportivo pre-infortunio resta nettamente più basso del rientro allo sport in senso generico, una distinzione spesso persa quando si guarda un solo numero; lo studio non ha un gruppo di controllo."], "mix": ["Il rinforzo laterale extra-articolare del ginocchio tiene bene a sei anni", "In un gruppo francese di 265 pazienti operati di legamento crociato anteriore con l'aggiunta di un rinforzo esterno del ginocchio (una fascia di tessuto che stabilizza il lato esterno dell'articolazione), la rottura dell'innesto a distanza di anni è stata rara e la maggior parte dei pazienti è tornata a fare sport.", "Nota sul limite: tornare a fare sport non significa tornare allo stesso livello di prima — quella percentuale è più bassa — ed è un aspetto da discutere in modo realistico prima dell'intervento."], "paz": ["Un rinforzo esterno del ginocchio, insieme alla ricostruzione del legamento, tiene bene negli anni", "In un gruppo di pazienti operati di ricostruzione del legamento crociato anteriore con l'aggiunta di un rinforzo sul lato esterno del ginocchio, la maggior parte è tornata a praticare sport, e solo una piccola parte ha avuto una nuova rottura dell'innesto a distanza di anni.", "Nota rassicurante: i risultati a lungo termine sono buoni; è comunque onesto sapere che tornare allo sport non significa sempre tornare esattamente al livello di prima dell'infortunio."], "kw": "rinforzo laterale ginocchio, legamento crociato anteriore, rientro allo sport"}, "3": {"prof": ["Un'instabilità del menisco invisibile all'artroscopia esiste davvero", "In una coorte giapponese di pazienti operati di ricostruzione del legamento crociato anteriore, il sondaggio sistematico della zona d'attacco posteriore del menisco mediale trova un'instabilità funzionale in oltre 4 casi su 10 nonostante un aspetto artroscopico visivamente normale, soprattutto quando la lassità del ginocchio prima dell'intervento è già alta.", "Nota critica: lo studio descrive quanto è frequente questa instabilità occulta, non se trattarla cambi l'esito a distanza — una domanda ancora aperta."], "mix": ["Un'instabilità del menisco invisibile all'artroscopia esiste davvero", "Durante l'intervento di ricostruzione del legamento crociato anteriore, un gruppo giapponese ha controllato manualmente (non solo con lo sguardo) la parte posteriore del menisco mediale: in molti casi con aspetto visivamente normale hanno trovato comunque un punto instabile, soprattutto nei ginocchi già più lassi prima dell'operazione.", "Nota sul limite: sapere che l'instabilità c'è non dice ancora se e come trattarla cambi il risultato per il paziente — serve ancora ricerca su questo punto."], "paz": ["Un problema nascosto del menisco che l'occhio da solo non vede sempre", "Durante l'intervento al legamento del ginocchio, alcuni chirurghi giapponesi hanno scoperto che una parte del menisco può essere instabile anche quando sembra a posto a prima vista, e che questo capita più spesso nei ginocchi già più «lassi» prima dell'operazione.", "Nota rassicurante: è un controllo in più che un chirurgo attento può fare durante lo stesso intervento, senza bisogno di altri esami; lo studio non dice ancora se cambi il risultato finale, ma aiuta a capire meglio il ginocchio operato."], "kw": "menisco, lesione ramp, legamento crociato anteriore"}, "4": {"prof": ["Lesioni multilegamentose del ginocchio: i punti ancora aperti", "Una revisione narrativa sulla gestione delle lesioni multilegamentose del ginocchio ricorda la ricostruzione anatomica in un solo tempo entro due-tre settimane, l'innesto autologo per il legamento crociato anteriore nei pazienti giovani e la mobilizzazione precoce, segnalando che l'artrosi post-traumatica arriva fino al 71,7% dei pazienti in alcune serie oltre i sette anni.", "Nota critica: è una revisione narrativa di un solo autore, non sistematica: la cifra sull'artrosi a distanza viene da «alcune serie», non da una stima aggregata con incertezza propria."], "mix": ["Lesioni multilegamentose del ginocchio: i punti ancora aperti", "Quando più legamenti del ginocchio si rompono insieme, una revisione della letteratura ricorda che operare presto (entro due-tre settimane) e muovere precocemente l'articolazione dopo l'intervento dà i risultati migliori, ma che l'artrosi può comparire anche a distanza di molti anni in una parte importante dei pazienti.", "Nota sul limite: la cifra sull'artrosi a lungo termine viene da alcuni studi soltanto, non da una stima complessiva affidabile — va presa come un segnale, non come una previsione precisa."], "paz": ["Quando più legamenti del ginocchio si rompono insieme: che cosa aspettarsi", "Una lesione che coinvolge più legamenti del ginocchio insieme è rara ma seria. Una revisione della letteratura medica ricorda che operare in tempi ragionevoli e muovere presto il ginocchio dopo l'intervento aiuta il recupero, ma che con gli anni può comparire usura dell'articolazione in una parte non piccola dei pazienti.", "Nota rassicurante: i risultati a breve e medio termine sono in genere buoni; parlarne apertamente con il chirurgo, anche del rischio a lungo termine, aiuta ad affrontare con più serenità il percorso di cura."], "kw": "lesione multilegamentosa, ginocchio, ricostruzione legamenti"}, "5": {"prof": ["La protesi di ginocchio robot-assistita allinea meglio, il resto resta nella media", "Una revisione sistematica di 52 studi confronta la protesi totale di ginocchio robot-assistita con la tecnica convenzionale: allineamento più preciso della componente, degenza più breve e minor sanguinamento, ma differenze minime sugli esiti riferiti dal paziente; l'abstract non riporta le dimensioni dell'effetto con i relativi intervalli di confidenza.", "Nota critica: la revisione unisce piattaforme robotiche diverse, non isolate per marca, e non fornisce un dato di sopravvivenza dell'impianto a lungo termine."], "mix": ["La protesi di ginocchio robot-assistita allinea meglio, il resto resta nella media", "Una revisione di oltre cinquanta studi confronta la protesi di ginocchio guidata da un robot con quella eseguita in modo tradizionale: la componente si posiziona in modo più preciso, la degenza in ospedale è più breve, ma su come si sente il paziente dopo l'intervento le differenze restano piccole.", "Nota sul limite: lo studio mette insieme sistemi robotici diversi tra loro, e non dice ancora se questi vantaggi tecnici si traducano in una protesi che dura più a lungo."], "paz": ["La protesi di ginocchio fatta con l'aiuto di un robot: che differenza fa davvero", "Un'analisi di più studi mostra che la protesi di ginocchio eseguita con l'assistenza di un robot posiziona la protesi in modo più preciso e permette una degenza ospedaliera un po' più breve, ma sul come ci si sente dopo l'intervento la differenza con la tecnica tradizionale resta piccola.", "Nota rassicurante: entrambe le tecniche, robotica e tradizionale, danno buoni risultati nelle mani di un chirurgo esperto; il robot è uno strumento in più di precisione, non una garanzia di risultato diverso."], "kw": "protesi ginocchio robotica, chirurgia robotica, artroprotesi"}, "6": {"prof": ["Nel paziente diabetico, la protesi parziale ha meno complicanze della totale", "Un database giapponese di 5.783 coppie di pazienti appaiate per propensione mostra che, nei pazienti con diabete di tipo 2, la protesi totale di ginocchio si associa a più trombosi venosa profonda e delirio postoperatorio rispetto alla monocompartimentale, con degenza più lunga; differenze simili si osservano anche nei pazienti non diabetici.", "Nota critica: le due tecniche non sono intercambiabili sullo stesso ginocchio — è un confronto fra popolazioni chirurgiche diverse per indicazione, non un trial randomizzato fra due opzioni equivalenti."], "mix": ["Nel paziente diabetico, la protesi parziale ha meno complicanze della totale", "In una grande casistica giapponese di pazienti diabetici, chi ha ricevuto una protesi parziale di ginocchio (limitata a una parte dell'articolazione) ha avuto meno trombosi venosa e meno confusione mentale dopo l'intervento rispetto a chi ha ricevuto una protesi totale, con una degenza più breve.", "Nota sul limite: le due protesi si usano per situazioni diverse dell'articolazione, quindi il confronto non dice che la parziale sia sempre preferibile — solo che, quando entrambe sono possibili, il decorso postoperatorio nel diabetico pesa a favore della parziale."], "paz": ["Diabete e protesi di ginocchio: la parziale sembra avere un decorso più semplice", "Uno studio su molti pazienti diabetici giapponesi mostra che chi riceve una protesi limitata a una parte del ginocchio ha, nei giorni dopo l'intervento, meno complicazioni (come trombosi o confusione mentale) rispetto a chi riceve una protesi dell'intero ginocchio, e resta in ospedale un po' meno.", "Nota rassicurante: non tutti i ginocchi sono adatti alla protesi parziale — lo decide il chirurgo in base a quanto è danneggiata l'articolazione — ma quando lo è, questo studio è un motivo in più di tranquillità per chi ha il diabete."], "kw": "protesi ginocchio diabete, protesi parziale, artroprotesi totale"}, "7": {"prof": ["Nella revisione di protesi di ginocchio, il tempo trascorso indica la causa più probabile", "Una coorte multicentrica cilena su 150 prime revisioni di protesi totale di ginocchio mostra che l'infezione è la causa più frequente nei primi due anni, mentre la mobilizzazione asettica lo diventa successivamente, con un'associazione forte fra revisione tardiva e mobilizzazione asettica.", "Nota critica: gli stessi autori avvertono che lo studio non stima il rischio di revisione dopo la protesi primaria, solo la distribuzione delle cause fra le revisioni già avvenute — soggetta a bias di selezione."], "mix": ["Nella revisione di protesi di ginocchio, il tempo trascorso indica la causa più probabile", "In una casistica cilena su 150 pazienti rioperati dopo una protesi di ginocchio, la causa cambia con il tempo trascorso dall'intervento iniziale: infezione più spesso nei primi due anni, allentamento della protesi più spesso dopo — un'informazione utile per orientare gli accertamenti prima ancora dei risultati degli esami.", "Nota sul limite: lo studio fotografa chi è già stato rioperato, non calcola quanto sia probabile dover essere rioperati in generale dopo una protesi."], "paz": ["Se la protesi di ginocchio va rioperata, il tempo trascorso aiuta a capire perché", "Uno studio su pazienti cileni che hanno dovuto rifare l'intervento di protesi di ginocchio mostra che, se il problema si presenta nei primi due anni, la causa più comune è un'infezione; se si presenta più tardi, la causa più comune è che la protesi si è allentata nel tempo.", "Nota rassicurante: la necessità di rioperare una protesi di ginocchio è un evento raro nella grande maggioranza dei pazienti; conoscere le cause più frequenti aiuta il chirurgo a indagare nel modo giusto se dovesse succedere."], "kw": "revisione protesi ginocchio, mobilizzazione protesi, infezione protesi"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Journal of ISAKOS",h:"Riparare la radice meniscale laterale nel LCA non cambia il punteggio",v:"Meta-analisi di 9 studi comparativi, 910 ginocchia: la riparazione della radice meniscale posteriore laterale insieme alla ricostruzione del LCA non mostra differenze significative su IKDC, Lysholm, Tegner o lassità strumentale rispetto alla ricostruzione isolata; guarigione tecnica nell'81% dei casi, ma il confronto diretto riparazione-contro-non-riparazione resta scarso.",ax:"Ade-Conde, Duru, Skaik, Macciacchera, Daniel Bouchard, Duart Vincent, Daud, Matache, Abouali",date:"set 2026",meta:"revisione sistematica e meta-analisi, 9 studi retrospettivi comparativi, 910 ginocchia · [III]",pmid:'42777823',doi:'10.1016/j.jisako.2026.101222',journal:"Journal of ISAKOS",authors:"Ade-Conde M, Duru DO, Skaik K, Macciacchera M, Daniel Bouchard M, Duart Vincent A, Daud A, Matache BA, Abouali J",design:"Revisione sistematica e meta-analisi di studi comparativi retrospettivi su ricostruzione primaria del LCA con riparazione concomitante di una lesione della radice posteriore del menisco laterale (LMPRT), confrontata con ricostruzione isolata del LCA a menisco laterale integro o, in due studi, con LMPRT non trattate; ricerca su MEDLINE, Embase e CENTRAL fino al 23 maggio 2026, qualità metodologica valutata con MINORS, modelli a effetti casuali per le differenze medie (MD) con IC 95%.",pop:"9 studi retrospettivi comparativi, 910 ginocchia (340 con riparazione della radice laterale concomitante, 570 comparatori); 7 studi confrontano con LCA isolato a menisco integro, 2 studi confrontano riparazione contro LMPRT non trattata; follow-up minimo 1 anno.",results:"Nessuna differenza statisticamente significativa fra riparazione concomitante e ricostruzione isolata su IKDC (differenza media -0,43 punti; IC 95% -2,78/1,93; p=0,72; I²=15%), Lysholm (+0,82; IC 95% -1,25/2,89; p=0,44; I²=42%), Tegner (-0,09; IC 95% -0,43/0,24; p=0,59; I²=42%) o traslazione tibiale anteriore all'artrometro (+0,23mm; IC 95% -0,04/0,51; p=0,09; I²=73%); nessuna differenza sulle cinque sottoscale del KOOS (tutte p≥0,424, eterogeneità I²=63-84%). I due studi che confrontano riparazione contro radice non trattata non trovano differenze significative su IKDC o Lysholm a 2 anni (tutte p>0,05). Guarigione secondo i criteri di ogni studio in 89/110 riparazioni (81%).",concl:"Gli autori concludono che la ricostruzione del LCA con riparazione concomitante della radice meniscale laterale dà esiti favorevoli a breve termine, ma il confronto con la ricostruzione isolata a menisco integro non dimostra un beneficio della riparazione, e l'evidenza diretta che confronta riparazione con non-riparazione resta limitata; servono studi futuri sulla tecnica di riparazione e sugli esiti condrali e radiografici a lungo termine.",limits:"Il confronto principale (riparato contro menisco integro) non risponde alla domanda clinica reale — se riparare convenga rispetto a non riparare una radice lesa — e i soli 2 studi che rispondono a quella domanda sono troppo pochi per un intervallo di confidenza informativo · tecnica di fissazione della radice non standardizzata né stratificata fra gli studi inclusi · eterogeneità moderata-alta su più esiti (I² fino al 73-84%).",perte:"La radice che tu riparifichi più spesso con tecnica transtibiale è quella mediale; questo lavoro riguarda la radice LATERALE e non stratifica per tecnica di fissazione, quindi non si applica direttamente al tuo gesto — ma il messaggio di fondo vale anche per te: la riparazione della radice, per quanto tecnicamente fattibile (guarigione 81%), non ha ancora un confronto diretto solido contro il non trattarla nella lesione posteriore laterale. Un argomento in più per non presentarla come garanzia di risultato quando ne parli con un paziente."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Il rinforzo laterale extra-articolare tiene bene a sei anni",v:"265 pazienti, follow-up medio 84 mesi: la ricostruzione del LCA con tenodesi laterale extra-articolare (tecnica MacIntosh modificata più augmentazione di gracilis) dà una rottura dell'innesto del 4,9% e un rientro allo sport nel 91,6% dei casi, ma al livello pre-infortunio solo nel 44,8%.",ax:"Bouyge, Gerometta, Valentin, Moussa, Lepidas, Khiami, Meyer, Grimaud, Lefèvre, Bohu, Hardy",date:"set 2026",meta:"coorte retrospettiva monocentrica (coorte FAST francese), 265 pazienti, follow-up medio 84,3±10,7 mesi · [IV]",pmid:'42775564',doi:'10.1002/ksa.70626',journal:"Knee Surgery, Sports Traumatology, Arthroscopy",authors:"Bouyge B, Gerometta A, Valentin E, Moussa M, Lepidas N, Khiami F, Meyer A, Grimaud O, Lefèvre N, Bohu Y, Hardy A",design:"Studio di coorte retrospettivo monocentrico su pazienti della coorte prospettica francese FAST (French Prospective Anterior Cruciate Ligament Reconstruction Cohort Study) sottoposti a ricostruzione primaria del LCA con tecnica combinata intra- ed extra-articolare — tenodesi extra-articolare laterale secondo MacIntosh modificato, con augmentazione di gracilis — fra gennaio 2015 e ottobre 2019; esito primario la rottura dell'innesto, esiti secondari punteggi soggettivi, rientro allo sport e complicanze; regressione logistica multivariabile per i fattori associati a rottura e a rientro al livello pre-infortunio.",pop:"265 pazienti analizzati per rottura dell'innesto e complicanze, follow-up medio 84,3±10,7 mesi; 252 pazienti valutabili per gli esiti funzionali dopo esclusione delle rotture; 249 praticavano sport prima dell'infortunio.",results:"Rottura dell'innesto in 13 pazienti (4,9%); altre complicanze in 5 (1,9%); ulteriori interventi chirurgici (esclusa la revisione del LCA) in 13 (4,9%), soprattutto meniscectomia per lesioni meniscali secondarie (4,2%). IKDC soggettivo mediano 92,0, Lysholm mediano 95,0 (miglioramento rispetto al preoperatorio, p<0,001). Rientro allo sport in 228/249 (91,6%), allo stesso sport in 154 (61,8%), al livello pre-infortunio in 69 (44,8%); tempo mediano al rientro 8,0 mesi. Età più giovane e lesione del menisco mediale associate in modo indipendente a un rischio più alto di rottura dell'innesto.",concl:"Gli autori concludono che la ricostruzione primaria del LCA con tecnica MacIntosh modificata e augmentazione di gracilis dà un tasso di rottura dell'innesto basso, punteggi funzionali favorevoli e un tasso di rientro allo sport complessivamente alto a un follow-up minimo di sei anni.",limits:"Livello IV, serie di casi retrospettiva senza gruppo di controllo: nessun confronto diretto con la ricostruzione isolata o con altre tecniche di rinforzo laterale · innesto usato per la componente intra-articolare del LCA non specificato nell'abstract · rientro al livello pre-infortunio (44,8%) nettamente più basso del rientro allo sport generico (91,6%), un divario spesso sottostimato quando si guarda un solo numero.",perte:"Non è la tua tecnica esatta — tu usi il Lemaire modificato con fissazione onlay, questo è un MacIntosh modificato con augmentazione di gracilis, e l'abstract non specifica l'innesto per il LCA — ma è un altro tassello che va nella stessa direzione filosofica: il rinforzo laterale extra-articolare, in famiglie tecniche diverse, continua a mostrare tassi di rottura bassi a follow-up lunghi. Il numero da portare in ambulatorio è la forbice fra rientro allo sport (91,6%) e rientro al livello pre-infortunio (44,8%): utile per calibrare le aspettative del paziente."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"SICOT-J",h:"L'instabilità meniscotibiale invisibile in artroscopia esiste davvero",v:"70 ginocchia senza lesione di ramp visibile durante la ricostruzione del LCA: il sondaggio sistematico trova instabilità meniscotibiale funzionale nel 41,4% dei casi, associata a maggiore lassità antero-tibiale preoperatoria e a vascolarizzazione ridotta della zona ramp.",ax:"Takahashi, Matsumoto",date:"set 2026",meta:"coorte retrospettiva monocentrica, 70 ginocchia (di 171 esaminate), Giappone · [III]",pmid:'42775800',doi:'10.1051/sicotj/2026067',journal:"SICOT-J",authors:"Takahashi T, Matsumoto T",design:"Studio di coorte retrospettivo su pazienti sottoposti a ricostruzione primaria del LCA fra gennaio 2021 e gennaio 2026: la zona ramp del menisco mediale valutata con visione transcondilare standardizzata seguita da sondaggio sistematico; instabilità meniscotibiale definita come mobilità abnorme del corno posteriore del menisco mediale all'inserzione meniscotibiale in assenza di lesione strutturale visibile; regressione logistica multivariabile e analisi ROC per i fattori associati.",pop:"171 pazienti valutati, 113 eleggibili; 43 con lesione di ramp visibile esclusi, 70 analizzati per instabilità meniscotibiale occulta.",results:"Instabilità meniscotibiale identificata in 29/70 pazienti (41,4%) nonostante l'aspetto artroscopico normale della zona ramp. Associati in modo indipendente: differenza lato-lato preoperatoria nella traslazione tibiale anteriore (OR 1,81; p=0,0024) e vascolarizzazione ridotta della zona ramp (OR 3,36; p=0,047). Una soglia di 5,0mm di differenza lato-lato ha discriminazione accettabile (AUC 0,734).",concl:"Gli autori concludono che l'instabilità meniscotibiale può essere presente nonostante un aspetto artroscopico normale della zona ramp, ed è associata a maggiore instabilità antero-tibiale preoperatoria: il sondaggio sistematico, non la sola ispezione visiva, è essenziale per identificare questa anomalia funzionale occulta.",limits:"Monocentrico, retrospettivo, un solo gruppo chirurgico giapponese · definizione di «instabilità meniscotibiale» basata sul sondaggio manuale dell'operatore, non su una misura strumentale oggettiva o riproducibile fra osservatori · nessun dato sull'esito clinico di trattare o non trattare l'instabilità occulta trovata: lo studio descrive l'incidenza, non ne dimostra la rilevanza clinica a distanza.",perte:"Un motivo in più per non fermarti alla sola ispezione visiva della zona ramp quando ricostruisci un LCA: qui il sondaggio sistematico trova un'instabilità funzionale in oltre 4 ginocchia su 10 con aspetto artroscopico normale, soprattutto quando la lassità antero-tibiale preoperatoria è già alta. Lo studio non dice ancora se trattarla cambi l'esito — ma dice che il solo sguardo può non bastare."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Cureus",h:"Le lesioni multilegamentose, i punti ancora aperti",v:"Revisione narrativa sulle lesioni multilegamentose del ginocchio: ricostruzione anatomica in singolo tempo entro 2-3 settimane, innesto autologo preferito per il LCA, mobilizzazione precoce; l'artrosi post-traumatica arriva fino al 71,7% in alcune serie oltre i sette anni.",ax:"Saráchaga Mendoza",date:"set 2026",meta:"revisione narrativa (PubMed, Cochrane, Google Scholar, 2010-2026) · [V]",pmid:'42774985',doi:'10.7759/cureus.116740',journal:"Cureus",authors:"Saráchaga Mendoza MA",design:"Revisione narrativa sulla diagnosi, il trattamento e le controversie attuali nelle lesioni multilegamentose del ginocchio (rottura simultanea di due o più legamenti principali), basata su ricerca in PubMed, Cochrane Library e Google Scholar dal 2010 al 2026.",pop:"Nessuna coorte propria: sintesi narrativa della letteratura su lesioni multilegamentose del ginocchio.",results:"La classificazione di Schenck resta il riferimento ma la sua categoria iniziale è imprecisa e non predice in modo affidabile la lesione neurovascolare. La risonanza magnetica è lo standard diagnostico, con soglia bassa per l'angio-TC in caso di sospetta lesione vascolare. La ricostruzione anatomica in un solo tempo chirurgico entro due-tre settimane si associa a minori lesioni meniscali e condrali secondarie. L'autoinnesto è preferito per il LCA nei pazienti giovani, mentre autoinnesto e allograft danno risultati comparabili per LCP e complesso collaterale. La mobilizzazione precoce si associa a minore artrofibrosi senza compromettere gli innesti. Gli esiti funzionali sono accettabili a breve-medio termine ma peggiorano dal settimo anno in poi, con artrosi post-traumatica fino al 71,7% dei pazienti in alcune serie — cifra citata dalla review senza un proprio intervallo di confidenza.",concl:"L'autore conclude che artrofibrosi e instabilità residua sono le complicanze più frequenti, la lesione neurovascolare la più grave, e che timing chirurgico, scelta dell'innesto e sequenza della ricostruzione restano le domande aperte principali, da chiarire con studi comparativi.",limits:"Revisione narrativa monoautore, non sistematica: nessun protocollo PRISMA, selezione della letteratura non riproducibile · il dato di artrosi post-traumatica al 71,7% è citato da «alcune serie» senza indicarne disegno o numerosità · nessuna sintesi quantitativa propria, solo descrizione della letteratura esistente.",perte:"Una fotografia utile delle domande ancora aperte proprio nell'area delle multilegamentose che tratti: timing (qui raccomandato entro 2-3 settimane), innesto (autologo per il LCA, comparabile per LCP e collaterali) e mobilizzazione precoce. Il numero da tenere a mente per il colloquio col paziente è quello sull'artrosi post-traumatica a distanza — fino al 71,7% in alcune serie, anche se non è una stima aggregata con incertezza propria."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"The International Journal of Medical Robotics and Computer Assisted Surgery",h:"La protesi robotica allinea meglio, il resto è nella media",v:"Revisione sistematica di 52 studi: la protesi di ginocchio robot-assistita allinea la componente in modo più preciso della tecnica convenzionale, con degenza più breve e minore sanguinamento; sugli esiti riferiti dal paziente le differenze restano minime, e l'abstract non riporta le dimensioni dell'effetto con i loro intervalli di confidenza.",ax:"Omairi, Kenny, Al-Dadah",date:"set 2026",meta:"revisione sistematica e meta-analisi, 52 studi (RCT e coorti osservazionali) · [III, disegni eterogenei]",pmid:'42775510',doi:'10.1002/rcs.70228',journal:"The International Journal of Medical Robotics and Computer Assisted Surgery",authors:"Omairi A, Kenny R, Al-Dadah O",design:"Revisione sistematica e meta-analisi (registrata su PROSPERO, CRD42023410154) di trial randomizzati controllati e coorti osservazionali che confrontano la protesi totale di ginocchio robot-assistita (RTKA) con la tecnica convenzionale (CTKA): allineamento (angolo anca-ginocchio-caviglia, angoli delle componenti femorale e tibiale), esiti riferiti dal paziente, tempo operatorio, degenza, perdita ematica e complicanze; dati aggregati con modelli a effetti casuali, eterogeneità con statistica I² in R.",pop:"52 studi inclusi, randomizzati e osservazionali; popolazione complessiva non riportata come cifra unica nell'abstract.",results:"La protesi robot-assistita mostra una precisione superiore nell'allineamento della componente e riduce i valori anomali (outlier) di allineamento; la maggior parte degli esiti riferiti dal paziente mostra differenze minime fra le due tecniche. Il tempo operatorio è più lungo con la tecnica robotica, ma la degenza ospedaliera è più breve; la perdita ematica è inferiore con la tecnica robotica. Marcatori infiammatori e tassi di revisione mostrano risultati incoerenti fra gli studi. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract per nessuno di questi confronti.",concl:"Gli autori concludono che la protesi robot-assistita migliora l'allineamento meccanico e ne riduce gli outlier, con vantaggi modesti a breve termine su esiti riferiti dal paziente e parametri di recupero, ma che i benefici clinici a lungo termine richiedono ulteriori studi di alta qualità con esiti standardizzati.",limits:"L'abstract non riporta una sola dimensione dell'effetto pooled con intervallo di confidenza: l'affermazione di «superiorità» sull'allineamento non è quantificabile dalla sola fonte disponibile · pool eterogeneo di RCT e studi osservazionali su piattaforme robotiche diverse, non isolato sul sistema VELYS che usi tu · nessun dato di sopravvivenza dell'impianto a lungo termine.",perte:"Un'altra fotografia — dopo lo scoping review NICE di ieri — della stessa domanda sulla tua piattaforma robotica: allineamento più preciso, recupero perioperatorio leggermente migliore, ma qui l'abstract non dà nemmeno un numero con intervallo di confidenza da citare, e lo studio mette insieme piattaforme diverse dalla tua VELYS. Resta un segnale di direzione, non un dato da portare in una discussione tecnica."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Nel diabetico, la mono ha meno complicanze della protesi totale",v:"Database giapponese, 5783 coppie appaiate per propensione: nei pazienti diabetici la protesi totale si associa a più trombosi venosa profonda (OR 1,46) e delirio postoperatorio (OR 2,35) rispetto alla monocompartimentale, con degenza più lunga.",ax:"Mori, Tarasawa, Kanabuchi, Tanaka, Mori, Fushimi, Aizawa, Fujimori",date:"set 2026",meta:"coorte retrospettiva di database nazionale, propensity-matched, 5783 coppie · [III]",pmid:'42774875',doi:'10.1002/jeo2.70917',journal:"Journal of Experimental Orthopaedics",authors:"Mori Y, Tarasawa K, Kanabuchi R, Tanaka H, Mori N, Fushimi K, Aizawa T, Fujimori K",design:"Studio di coorte retrospettivo sul database amministrativo giapponese Diagnosis Procedure Combination: pazienti con diabete di tipo 2 sottoposti a protesi totale (TKA) o monocompartimentale (UKA) primaria per artrosi fra aprile 2016 e marzo 2023; appaiamento 1:1 per propensione su caratteristiche demografiche e cliniche; analisi aggiuntive nei pazienti senza diabete e analisi d'interazione sulla coorte complessiva.",pop:"263.838 pazienti eleggibili, 49.373 con diabete di tipo 2 sottoposti a TKA e 5.801 a UKA; 5.783 coppie appaiate per propensione analizzate.",results:"Dopo l'appaiamento, la TKA si associa a maggiore incidenza di trombosi venosa profonda (OR 1,46; IC 95% 1,29-1,66) e di delirio postoperatorio (OR 2,35; IC 95% 1,39-3,96) rispetto alla UKA, oltre a degenza più lunga, minore probabilità di dimissione diretta a domicilio e maggiore volume trasfuso. Differenze simili osservate anche nei pazienti senza diabete, senza interazione significativa fra stato diabetico e tipo di intervento per trombosi venosa profonda o delirio.",concl:"Gli autori concludono che, nei pazienti con diabete di tipo 2 sottoposti a protesi di ginocchio, la UKA ha un profilo perioperatorio a breve termine più favorevole della TKA, ma che questa differenza non è specifica del diabete: si osserva in modo simile anche nei pazienti non diabetici.",limits:"Dati amministrativi di database: nessun dettaglio su gravità dell'artrosi, indicazione specifica o tecnica chirurgica in nessuno dei due gruppi · confronto fra due popolazioni chirurgiche diverse per indicazione (mono e totale non sono intercambiabili sullo stesso ginocchio), più che un confronto randomizzato fra due opzioni equivalenti · esiti a breve termine, nessun dato di sopravvivenza dell'impianto.",perte:"Un argomento in più, su una popolazione ampia, per la tua propensione alla monocompartimentale quando il comparto e l'indicazione lo consentono in un paziente diabetico: meno trombosi, meno delirio postoperatorio, degenza più corta. Il limite da ricordare in ambulatorio: non è la stessa popolazione chirurgica, quindi non è la prova che la mono sia «meglio» in senso assoluto — è la prova che, quando entrambe sono un'opzione ragionevole, il profilo perioperatorio pesa a favore della mono nel diabetico."},{n:7,mono:"m-gray",dot:"green",sec:"res",j:"Journal of ISAKOS",h:"Nella revisione di protesi, il tempo trascorso indica la causa",v:"Coorte multicentrica cilena, 150 revisioni: nei primi due anni la causa più frequente è l'infezione (34%), dopo i due anni è la mobilizzazione asettica (53,6%), con un'associazione forte fra revisione tardiva e mobilizzazione asettica (OR 6,70).",ax:"Villanueva, Duque, Lorca, Acurio, Durruty, Maldonado, Abarca, Díaz Del Valle, Manriquez, Rodriguez, Poblete",date:"set 2026",meta:"coorte retrospettiva multicentrica, 5 centri cileni, 150 pazienti · [III]",pmid:'42777824',doi:'10.1016/j.jisako.2026.101223',journal:"Journal of ISAKOS",authors:"Villanueva JI, Duque WG, Lorca MH, Acurio PE, Durruty EP, Maldonado VA, Abarca AT, Díaz Del Valle C, Manriquez HH, Rodriguez RC, Poblete DF",design:"Studio di coorte retrospettivo non consecutivo multicentrico su 150 pazienti sottoposti a prima revisione di protesi totale di ginocchio in cinque centri cileni fra il 2018 e il 2026; revisioni classificate come precoci (<24 mesi) o tardive (≥24 mesi); confronto della distribuzione delle indicazioni registrate con test categoriali (procedura Monte Carlo a margine fisso per celle sparse) e regressione logistica aggiustata per età e sesso; analisi di sensibilità per anno di revisione, centro e tempo trattato come continuo.",pop:"150 pazienti, età media 70,1±9,5 anni, 97 (64,7%) donne; 53 revisioni precoci (35,3%), 97 tardive (64,7%).",results:"La distribuzione delle indicazioni differisce per tempistica (Monte Carlo p=0,0003; V di Cramér 0,41). L'infezione è l'indicazione precoce più frequente (18/53, 34,0%), la mobilizzazione asettica rappresenta oltre metà delle revisioni tardive (52/97, 53,6%). Dopo aggiustamento per età e sesso, la revisione tardiva si associa a maggiori probabilità che l'indicazione registrata sia la mobilizzazione asettica (OR aggiustato 6,70; IC 95% 2,80-16,00; p<0,001); la revisione precoce si associa a maggiori probabilità che l'indicazione sia l'infezione (OR aggiustato 3,21; IC 95% 1,40-7,34; p=0,006). Stime simili dopo aggiustamento per anno e centro e trattando il tempo come variabile continua.",concl:"Gli autori concludono che, fra le prime revisioni incluse, l'infezione è l'indicazione più frequente prima dei 24 mesi mentre la mobilizzazione asettica lo è successivamente; sottolineano però che queste associazioni restano soggette a bias di selezione, errata classificazione diagnostica e confondimento residuo, e non stimano il rischio di revisione causa-specifico dopo la protesi primaria.",limits:"Coorte non consecutiva, criteri di selezione non descritti in dettaglio · gli stessi autori dichiarano che lo studio non stima il rischio di revisione causa-specifico, solo la distribuzione delle indicazioni fra le revisioni già avvenute · nessun dato sull'impianto primario (marca, tecnica, eventuale uso di robotica) che potrebbe confondere l'associazione.",perte:"Un promemoria utile per il colloquio prima di una revisione: il tempo trascorso dalla protesi primaria orienta la causa più probabile, infezione nei primi due anni, mobilizzazione asettica dopo — utile per impostare la work-up prima ancora dei risultati degli esami. Gli stessi autori avvertono che non è una stima del rischio, solo una fotografia di chi è già stato rioperato."}];
var SUGGQ=[{"k": "kol", "n": "Alexandre Hardy", "w": "Clinique du Sport, Parigi, Francia", "r": "Ultimo autore della scheda 2 di oggi sulla tenodesi extra-articolare laterale (tecnica MacIntosh modificata con augmentazione di gracilis) in aggiunta alla ricostruzione del LCA: la Clinique du Sport di Parigi è un centro di riferimento su LCA e rinforzo laterale extra-articolare, con la coorte prospettica FAST alle spalle. Corrispondenza tecnica diretta con la tua pratica, dove esegui il Lemaire modificato onlay su tutti i pazienti operati di LCA — famiglia tecnica diversa (MacIntosh contro Lemaire), stesso principio del rinforzo laterale sistematico. Sostituisce la proposta di Gilbert Moatshe (23 settembre, nessun segnale dell'utente arrivato per farlo ruotare)."}];
var BRIEF_TEXT="Oggi il filo conduttore è una domanda che pesa più di una conferma: una tecnica che esegui davvero migliora l'esito, o funziona semplicemente perché il gesto è fattibile? Una meta-analisi di nove studi su 910 ginocchia guarda alla riparazione della radice meniscale posteriore laterale insieme alla ricostruzione del LCA — non la radice mediale che tratti più spesso con tecnica transtibiale, ma lo stesso principio — e trova che il confronto con la ricostruzione isolata a menisco integro non mostra un beneficio dimostrato; il confronto più onesto, riparare contro non riparare una radice davvero lesa, esiste solo in due studi piccoli. La guarigione tecnica resta comunque alta, 81%. L'ho scelto come lavoro del giorno perché è il tipo di dato che conta di più: non conferma né smentisce, dice con onestà quanto poco si sa ancora.\n\nSul rinforzo laterale extra-articolare, un'altra famiglia tecnica — MacIntosh modificato con augmentazione di gracilis, non il tuo Lemaire onlay — conferma a sei anni una rottura dell'innesto bassa (4,9%) su 265 pazienti, con un rientro allo sport del 91,6% ma al livello pre-infortunio solo nel 44,8%: una forbice utile da tenere a mente nel colloquio con un paziente.\n\nSulla protesi, tre segnali diversi: una revisione sistematica su 52 studi conferma che la protesi robot-assistita allinea meglio, ma senza numeri quantificabili nell'abstract; in Giappone, nei pazienti diabetici, la monocompartimentale ha meno trombosi venosa e meno delirio della totale su quasi 5800 coppie appaiate per propensione; in Cile, il tempo trascorso dalla protesi primaria orienta la causa più probabile della revisione — infezione nei primi due anni, mobilizzazione asettica dopo. Un'ultima revisione narrativa ricorda che le lesioni multilegamentose, anche trattate bene, arrivano fino al 71,7% di artrosi post-traumatica in alcune serie oltre i sette anni — un dato da portare nel colloquio prima dell'intervento, non dopo.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi parto da una domanda scomoda: una tecnica che fai da anni ha davvero un beneficio dimostrato, o funziona solo perché è fattibile?"}, {"chi": "B", "t": "Sembra il tema del lavoro del giorno."}, {"chi": "A", "t": "Esatto. Una meta-analisi di nove studi, 910 ginocchia, guarda alla riparazione della radice meniscale posteriore laterale insieme alla ricostruzione del LCA."}, {"chi": "B", "t": "E il confronto con chi ha il menisco integro?"}, {"chi": "A", "t": "Nessuna differenza significativa su funzione o stabilità. La riparazione guarisce bene tecnicamente, 81% dei casi, ma il confronto vero — riparare o no una radice davvero lesa — esiste solo in due studi piccoli."}, {"chi": "B", "t": "Quindi non sappiamo ancora se convenga farlo."}, {"chi": "A", "t": "Esatto, ed è per questo che l'ho scelto come lavoro del giorno: dice con onestà quanto poco sappiamo, invece di confermare o smentire a buon mercato."}, {"chi": "B", "t": "C'è altro sul rinforzo laterale, oggi?"}, {"chi": "A", "t": "Sì, un'altra tecnica — non la tua, un MacIntosh modificato con augmentazione di gracilis — conferma a sei anni una rottura dell'innesto bassa, sotto il 5%."}, {"chi": "B", "t": "E il rientro allo sport?"}, {"chi": "A", "t": "Alto in generale, 91,6%, ma al livello pre-infortunio solo il 44,8% — una forbice da spiegare bene al paziente."}, {"chi": "B", "t": "E sulla protesi?"}, {"chi": "A", "t": "Tre segnali: la protesi robotica allinea meglio ma senza numeri quotabili nell'abstract; nei diabetici giapponesi la parziale ha meno trombosi e delirio della totale; e in Cile il tempo dalla protesi primaria dice la causa più probabile della revisione."}, {"chi": "B", "t": "Infezione presto, allentamento tardi?"}, {"chi": "A", "t": "Esatto. E chiudo con un numero da portare nel colloquio prima dell'intervento, non dopo: nelle lesioni multilegamentose l'artrosi post-traumatica arriva fino al 71,7% in alcune serie oltre i sette anni."}];
